		if (mc.theWorld.playerEntities.size() <= 10) {

			players = 20;

		}else {

			players = mc.theWorld.playerEntities.size();

		}

		try {
			if (e.isPre() && timer1.hasTimeElapsed(2000 * players, true)) {

